+		const base64Data = "A".repeat(90_000);
+		const message = {
+			role: "user",
+			content: [{ type: "image", data: base64Data, mediaType: "image/png" }],
+		};
+
+		const tokens = estimateRequestInputTokens({ messages: [message] });
